"""
Thin wrapper around the authors' repo/ISER.py with a sklearn-compatibility shim.
The shim patches sklearn.utils.validation.check_is_fitted so that ISER (which
does not inherit from sklearn BaseEstimator) can still call it without raising
AttributeError on newer sklearn versions.
"""
import sklearn.utils.validation as val
import inspect

# --- sklearn-compatibility shim (do NOT edit repo/ISER.py) ---
_orig_check_is_fitted = val.check_is_fitted
def _patched_check_is_fitted(estimator, attributes=None, msg=None, all_or_any=all):
    try:
        return _orig_check_is_fitted(estimator, attributes, msg=msg, all_or_any=all_or_any)
    except Exception:
        return
val.check_is_fitted = _patched_check_is_fitted
# --------------------------------------------------------------

import sys
sys.path.insert(0, 'repo')
from ISER import ISER
import numpy as np
from sklearn.metrics import roc_auc_score


def build_isr(X, psi, seed, t=200, if_max_samples=256):
    """Build an ISER model with given psi (max_samples) and random seed."""
    model = ISER(
        max_samples=psi,
        n_estimators=t,
        if_max_samples=if_max_samples,
        random_state=seed,
        novelty=True,
    )
    model.fit(X)
    return model


def scores_from_model(model, X):
    """Return dict of method name -> score array for a fitted ISER model."""
    return {
        'ISER_A': model.ISER_A(X),
        'ISER_S': model.ISER_S(X),
        'ISER_IF': model.ISER_IF(X),
    }


def run_psi_grid(X, y, psi_grid, seeds, t=200, if_max_samples=256):
    """
    For each psi in psi_grid and each seed in seeds, fit ISER and compute AUC-ROC
    for ISER_A, ISER_S, ISER_IF. Returns a dict:
      results[method][psi] = list of per-seed AUCs
      best_psi[method] = psi with highest mean AUC
    """
    results = {'ISER_A': {}, 'ISER_S': {}, 'ISER_IF': {}}
    for psi in psi_grid:
        for method in results:
            results[method][psi] = []
        for seed in seeds:
            model = build_isr(X, psi, seed, t=t, if_max_samples=if_max_samples)
            scores = scores_from_model(model, X)
            for method in results:
                auc = roc_auc_score(y, scores[method])
                results[method][psi].append(auc)
    best_psi = {}
    for method in results:
        means = {psi: np.mean(v) for psi, v in results[method].items()}
        best_psi[method] = max(means, key=means.get)
    return results, best_psi
